// One job: turn an untrusted HTTP body into a bounded, typed object.
// Anything that fails the shape check is marked invalid rather than thrown,
// so the student gets a 422 with a sentence instead of a stack trace.
const incoming = $input.first().json || {};
const payload = incoming.body && typeof incoming.body === "object" ? incoming.body : incoming;

const text = String(payload.chatInput || "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "").trim().slice(0, 1200);
const sessionRaw = String(payload.sessionId || "");
const pageRaw = (payload.metadata && payload.metadata.page) || "";
const valid = text.length >= 2;

return [{
  json: {
    valid,
    chatInput: text,
    sessionId: /^[A-Za-z0-9_-]{8,64}$/.test(sessionRaw) ? sessionRaw : "unknown-session",
    page: /^\/[A-Za-z0-9/_.-]{0,180}$/.test(pageRaw) ? pageRaw : "",
    receivedAt: new Date().toISOString(),
  },
}];
